fn solve(x: i32) -> i32 {
    // Convert x to a string to easily determine the digit and its length
    let x_str = x.to_string();
    let d = x_str.chars().next().unwrap().to_digit(10).unwrap() as i32; // The digit
    let k = x_str.len() as i32; // The length of the number

    // Calculate the score
    let mut score = 0;

    // Add scores for all digits from 1 to d-1
    for digit in 1..d {
        // Each digit contributes 1 + 2 + 3 + 4 presses for lengths 1 to 4
        score += (1 + 2 + 3 + 4); // This is 10 presses for each digit
    }

    // Add scores for the current digit d up to the length k
    for length in 1..=k {
        score += length; // Each length contributes its length in presses
    }

    score
}